import{_ as a,P as o,d as s,e as r,x as t,q as i}from"./chunks/framework.BRr8VP3a.js";const b=JSON.parse('{"title":"Part 4 Empirical Questions, Outcome Contracts, and Conditional Formal Propositions","description":"","frontmatter":{"title":"Part 4 Empirical Questions, Outcome Contracts, and Conditional Formal Propositions","xkChars":0,"xkWords":13513,"xkLessons":{"4.5":{"title":"History may act through a sufficient present carrier","lead":"The absence of an extra G3 increment need not erase historical formation or ordinary learning.","explanation":["Separate three questions: how earlier experience formed the current state, how a present carrier retains and transmits its effect, and whether history adds information or an effect conditional on the declared current representation. G3 is the third question.","When earlier practice H forms skill S and S affects outcome Y, conditioning on a sufficiently informative S can remove H’s extra predictive contribution. That does not cancel the formation or use of skill. Conversely, an unsupported G3 result cannot by itself prove either process occurred.","Carrier claims require longitudinal evidence about formation, retention or replenishment, and later operation, plus discriminating causal evidence for causal claims. Do not omit a known current carrier simply to make historical data appear incrementally valuable."],"distinctions":[{"leftTitle":"Carrier route","leftText":"Historical formation and later effects through a present state.","rightTitle":"Historical-increment route","rightText":"Additional information or effect beyond an explicit current representation."}],"teachingExamples":[{"title":"Practice, skill, and a later task","text":"Assume practice changes a measurable skill and the later task is fully determined by that skill. The practice can matter causally while adding no predictive information once skill is known.","assumptions":"A stipulated mediated relation; no hidden empirical claim.","boundary":"Real measurements may fail to capture the full current carrier."}],"boundaries":["A predictive increment does not by itself establish a causal historical effect.","Ordinary domain evidence for learning keeps its own supported scope."],"questionAnswers":[{"question":"Does a longitudinal study automatically test G3?","answer":"No. It must test the specified additional increment conditional on its declared present representation, with the appropriate design.","basis":"Theory v2, §4.5, with the distinctions explained above."}],"caseLinks":[{"title":"History, records, and learning","href":"/en/concepts/history"},{"title":"London taxi trainees","href":"/en/cases/london-taxi-learning"}],"sourceRefs":[{"section":"4.5","startLine":678,"endLine":699}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-04#section-4-5","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§4.5; English reading edition, lines 678–699","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"4.6":{"title":"A useful prediction can fail under a new action","lead":"Preserve distinctions required by the intervention, not just by ordinary dynamics.","explanation":["A representation can combine states that behave alike under the observed process. Once an intervention changes their responses differently, the same coarse state can cease to determine the answer. Ordinary predictive sufficiency therefore does not automatically extend to intervention sufficiency.","The book’s two-state construction shows how a small additional variable can help. If the share p of A₁ within A is known, the specified intervention probability becomes 0.1 + 0.7p. The task does not require restoring every micro-level detail.","A repair to this answer is still bounded. Knowing p now does not supply its future update law, guarantee long-horizon closure, or establish sufficiency for another intervention. State the target, environment, horizon, admissible operations, and error criterion together."],"distinctions":[{"leftTitle":"Ordinary prediction","leftText":"May be sufficient under the existing transition process.","rightTitle":"Intervention response","rightText":"Must preserve differences relevant to the declared new operation."}],"teachingExamples":[{"title":"Two ordinary probabilities, two intervention responses","text":"A₁ and A₂ each move to B with probability 0.2 ordinarily. Under intervention their probabilities are 0.8 and 0.1. With share p, the mixture response is 0.1 + 0.7p.","assumptions":"All probabilities are stipulated by the source’s teaching construction.","boundary":"No real treatment effect or permission to intervene follows."}],"boundaries":["A model can be sufficient for one query and insufficient for another.","Prediction quality is not authorization to govern or intervene."],"questionAnswers":[{"question":"Does adding p establish its own dynamic closure?","answer":"No. The rule for updating the share and its sufficiency over the declared horizon require separate evidence or proof.","basis":"Theory v2, §4.6, with the distinctions explained above."}],"caseLinks":[{"title":"Prediction and intervention","href":"/en/concepts/prediction"}],"sourceRefs":[{"section":"4.6","startLine":700,"endLine":713}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/part-04#section-4-6","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§4.6; English reading edition, lines 700–713","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}],"model":"prediction"}}},"headers":[],"relativePath":"en/theory/part-04.md","filePath":"en/theory/part-04.md"}'),c={name:"en/theory/part-04.md"};function d(l,e,p,h,u,m){const n=o("SectionLesson");return s(),r("div",null,[e[0]||(e[0]=t('<div class="theory-source"><p><a id="part_4"></a></p><h1 id="part-title-4" tabindex="-1">Part 4 Empirical Questions, Outcome Contracts, and Conditional Formal Propositions <a class="header-anchor" href="#part-title-4" aria-label="Permalink to &quot;Part 4 Empirical Questions, Outcome Contracts, and Conditional Formal Propositions {#part-title-4}&quot;">​</a></h1><p>G1–G4 are four kinds of empirical question: whether a candidate grouping brings a conditional gain, whether a specified channel has an identifiable effect on a target transition, whether historical terms provide conditional increments beyond the current representation, and under which tasks, dynamics, and interventions a specified representation has closure. The question families themselves are not laws governing all objects. A specific G-instance registers both a factual assertion awaiting testing and rules for evidence; the two must not be conflated in writing. Whether an effect exists is determined by the world and the conditions at issue; whether the available evidence suffices to support that assertion is determined by the research design and results.</p><p>This Part separates empirical testing, the use of results, and formal proof. G instances answer factual questions; C contracts<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> specify which limited outputs can be assembled from an existing basis; F propositions state necessary relations under explicit mathematical conditions. Registering the same result again does not add independent evidence, nor does the number of passes under root families or contracts measure the usefulness of the entire framework.</p><h2 id="section-4-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.1</span><span class="xk-num__gap"></span></span>Contracts for Root Instances <a class="header-anchor" href="#section-4-1" aria-label="Permalink to &quot;4.1 Contracts for Root Instances {#section-4-1}&quot;">​</a></h2><p>This section provides a standard recording procedure for confirmatory testing. Under this procedure, each instance has two sections, pre-registration and results: pre-registration is completed before results are read, and the results section is appended after execution while preserving the original registration. What has not yet been run is explicitly recorded as not evaluated; times, observed values, or materials must not be fabricated. The two sections together determine what outcomes count as support, what outcomes count as refutation, and where conclusions may be extrapolated.</p><p>The single primary criterion used here is a default design to prevent choosing favorable results after they appear, not the only reasonable form for every study. Multiple outcomes, multiple models, joint criteria, confirmatory work following exploratory work, and sequential studies can each have valid designs, but the primary target or joint rule, selection procedure, stopping rule, and applicable handling of multiple comparisons must be stated in advance. The G and H subtypes with a single primary criterion below belong to this standard procedure. Materials outside the procedure are still evaluated according to their actual research designs; they must not be judged to have no knowledge value merely because their record fields have a different form. Nor are the four question families claimed to exhaust all scientific questions or to be logically independent axioms.</p><div class="xk-table"><table><thead><tr><th>Contract Section</th><th>Required Fields</th><th>Function</th></tr></thead><tbody><tr><td>Identity and freezing</td><td><code>instance_id</code>, <code>root_id</code>, <code>contract_version</code>, <code>preregistration_timestamp</code></td><td>Distinguish instances from root templates; use an immutable version and an auditable timestamp earlier than access to results to establish that the contract precedes the evidence</td></tr><tr><td>Candidate object</td><td><code>candidate_object_id</code>, <code>object_contract_id</code></td><td>Point to the D0 candidate object and its contract, preventing a name from being treated as grounds for a grouping gain or for object facts</td></tr><tr><td>Scale and target</td><td><code>scale_profile</code>, <code>time_window</code>, <code>identity_criterion</code>, <code>target_variables</code></td><td>Freeze SP, T, K, and the variables to be explained</td></tr><tr><td>Proposition instantiation</td><td><code>selected_subtype</code>, <code>selected_success_criterion</code>, <code>candidate_specification</code>, <code>zero_model</code>, <code>controls</code>, <code>model_classes</code></td><td>Select only one subtype before evidence appears, then only one success criterion from that subtype&#39;s admissible list; declare the candidate proposition, N0, controls, and model families</td></tr><tr><td>Sampling and extrapolation</td><td><code>sampling_unit</code>, <code>generalization_unit</code></td><td>Distinguish the source of the data from the scope to which the conclusion may be generalized</td></tr><tr><td>Decision rules</td><td><code>evaluation_metric</code>, <code>decision_threshold</code>, <code>decision_rule</code>, <code>null_decision_rule</code></td><td>Separate the positive-support check from the null-conclusion check; freeze the primary target or aggregation, model selection or ensembling, multiple comparisons, equivalence or sufficiency, statistical power or sensitivity, and tolerance</td></tr><tr><td>Mode and failure</td><td><code>evidence_mode</code>, <code>falsifier</code>, <code>pause_condition</code></td><td>Declare an exploratory, confirmatory, replication, or falsification mode, together with its ceiling on conclusions, falsification conditions, and suspension conditions</td></tr><tr><td>Deviations and status</td><td><code>deviation_record</code>, <code>preregistration_status</code></td><td>Record deviations, times, reasons, and impacts item by item; register <code>none</code> even when there is no deviation, and distinguish draft, frozen before evidence, completed under the frozen contract, and deviation after evidence</td></tr><tr><td>Results and time</td><td><code>result_timestamp</code>, <code>observed_primary_result</code>, <code>decision_rule_outcome</code>, <code>null_decision_rule_outcome</code>, <code>result_state</code></td><td>The result timestamp is later than the freezing timestamp; record only the observed results for the pre-frozen primary target and rules, record separately whether the positive-support check and the three null-conclusion checks pass, and close the instance using the closed set of four states</td></tr><tr><td>Evidence and analysis artifacts</td><td><code>evidence_refs</code>, <code>analysis_artifact_refs</code></td><td>Point to resolvable external materials, data freezes, code, models, or logs; internal concept identifiers, string prefixes, and self-reported conclusions cannot replace instances</td></tr></tbody></table></div><p>When the single-primary-criterion procedure is used, the selection rule is denoted <code>one_subtype_and_success_criterion_before_evidence</code>: one <code>selected_subtype</code> and one <code>selected_success_criterion</code> are determined before results appear. A joint or multi-outcome design must register its overall criterion separately; several individual items that did not pass must not be reassembled after the fact into a success. Evaluation metrics, positive thresholds, the null model, <code>decision_rule</code>, <code>null_decision_rule</code>, and falsification conditions are all frozen around that criterion. If the results are unfavorable, multiple subtypes or success criteria must not be combined after the fact, nor may the target, model, metric, or threshold be changed to rescue the empirical question family.</p><p><code>decision_rule</code> also closes off researcher degrees of freedom for multiple targets and models: if there is more than one target variable, a single primary target or aggregation rule must be frozen before results; if there is more than one model kind, a model-selection or ensemble rule must be frozen; if there are multiple comparisons, the correction rule must be frozen. Without these rules, an instance may have only one primary target and one primary model. <code>null_decision_rule</code> separately declares which equivalence or sufficiency test, statistical-power or sensitivity check, and tolerance can support N0. After execution, <code>decision_rule_outcome</code> must record the threshold, observed value, whether the criterion passed, and analysis artifacts in structured form; <code>null_decision_rule_outcome</code> records the three null-conclusion checks separately. Failure to pass the positive criterion is not the same as the null model having obtained support. If the null-conclusion checks were not frozen or have not all passed, the result remains <code>unsupported_or_undecided</code>.</p><p>Empirical instances use four summary states: <code>supported</code>, <code>unsupported_or_undecided</code>, <code>null_supported</code>, and <code>not_evaluated</code>. A summary state does not replace the specific conclusion: which predetermined criteria passed, which were countered by evidence, and which remain unresolved only because of insufficient precision or materials must be recorded separately. Clear counterevidence and an inability to judge must not be conflated as one kind of evidence. <code>supported</code> requires an eligible instance to pass the positive-support check; <code>null_supported</code> requires all of equivalence or sufficiency, statistical power or sensitivity, and tolerance to pass; <code>not_evaluated</code> means only that the instance has not yet been run. Result records must link <code>evidence_refs</code> and <code>analysis_artifact_refs</code>, and retain the result timestamp, contract version, and deviation record. Neither an abstract root family nor a correctly formatted instance ID can produce support on its own.</p><p>Whether an instance can support a C contract is also constrained by <code>support_eligibility_rule</code>. Positive support comes only from <code>confirmatory</code> or <code>replication</code> instances with auditable versions and timestamps, whose status before results is <code>frozen_before_evidence</code> and whose completion under the frozen contract is recorded as <code>completed_from_frozen</code>. It additionally requires <code>decision_rule_outcome.passed=true</code>, and the result state and external evidence/analysis artifacts must be resolvable. A <code>falsification</code> instance may support only a pre-registered falsification or null-model judgment; it must not be used in reverse to rescue positive G. Instances that are <code>exploratory</code>, <code>draft</code>, <code>deviated_after_evidence</code>, or have undisclosed deviations can only generate candidates, record deviations, or remain unresolved; they must not use formal-instance eligibility to support C branches that require that eligibility. Internal definitions, concept labels, and the framework&#39;s own descriptions do not constitute empirical support for an instance.</p><p>The scale invariants shared by the four roots include the preselected subtype, success criterion, <code>decision_rule</code>, and <code>null_decision_rule</code>; these must be retained during scale transfer and must not be replaced. An appeal may challenge the candidate object, subtype, success criterion, N0, primary target or aggregation, model selection or ensembling, multiple comparisons, controls, positive threshold, null-conclusion rule, data split, extrapolation unit, contract version, pre-registration status, deviation record, and falsification conditions. If any item is shown to have changed after results, support eligibility must be reduced. A version produced after the fact must not overwrite the frozen record.</p><h2 id="section-4-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.2</span><span class="xk-num__gap"></span></span>Human Empirical Instance Contracts <a class="header-anchor" href="#section-4-2" aria-label="Permalink to &quot;4.2 Human Empirical Instance Contracts {#section-4-2}&quot;">​</a></h2><p>H1, H4, and H5 are not universal empirical question families, but they are likewise abstract families of empirical hypotheses. They cannot acquire truth values through names, interface fields, or framework definitions. They use a separate <code>human_empirical_instance_contract</code>: in the identity fields, <code>claim_id</code> replaces <code>root_id</code>, and only H1, H4, and H5 are allowed. The remaining provisions governing the pre-registration section, results section, missing-value encoding, version freezing, stages, four result states, deviation disclosure, positive-support check, null-conclusion check, evidence references, and analysis artifacts are isomorphic to those in the root-instance contract. The corresponding instances are formally called H1-instance, H4-instance, and H5-instance; empirical truth belongs to these specific H-instance cases, not to abstract H propositions.</p><p>An H-instance must also preselect exactly one subtype and one success criterion for that subtype before results are read. The following table is the standard registration classification for the single-primary-criterion procedure, not an exhaustive classification of meaning, power, or historical carriers. If the object or design at issue falls outside the list, the testable question and research procedure must be stated separately; it must not be forced into a favorable category.</p><div class="xk-table"><table><thead><tr><th>Proposition</th><th>Subtype or Outcome Family of Which Exactly One Must Be Preselected</th><th>Admissible Success Criteria</th><th>Stopping Point for the Conclusion</th></tr></thead><tbody><tr><td>H1 Meaning and coordination</td><td>Choose one of three: resource allocation outcomes, action-choice outcomes, or coordination outcomes</td><td>The one among <code>meaning_arrangement_resource_allocation_effect</code>, <code>meaning_arrangement_action_choice_effect</code>, and <code>meaning_arrangement_coordination_outcome_effect</code> corresponding to the selected subtype</td><td>Register only a conditional orientation anchor within the specified object, scale, window, and outcome family; do not infer a unified inner state, genuine consent, or a common will</td></tr><tr><td>H4 Power, mediation, and reflexivity</td><td>Choose one of four: evidence coverage, safety of expression, object behavior, or reflexive response</td><td>The one among <code>position_or_mediation_evidence_coverage_effect</code>, <code>position_or_mediation_expression_safety_effect</code>, <code>mediation_or_publicity_behavioral_response_effect</code>, and <code>observation_or_publication_reflexive_response_effect</code> corresponding to the selected subtype</td><td>Register only masking, amplification, behavior, or reflexive response within the specified position, mediation, disclosure conditions, channel, and outcome family; do not infer malice, responsibility, or automatic real-world action</td></tr><tr><td>H5 Historical trace carriers</td><td>First preselect exactly one subtype among five carrier families: <code>institutional_or_textual_record</code>, <code>role_or_organizational_arrangement</code>, <code>habit_or_practice</code>, <code>trauma_record</code>, and <code>collective_memory_carrier</code>; then provide the <code>selected_carrier_family_id</code> corresponding to that subtype and one specific atomic <code>selected_carrier</code> reference</td><td>Choose one of three: <code>threshold_persistence_over_preregistered_window</code>, <code>repeat_detection_across_preregistered_windows</code>, or <code>persistence_after_event_or_exposure_end</code></td><td>Register only candidate traces within the specified carrier, observables, and window; obtain separate evidence under §4.5 for subsequent carrier effects; only historical increments beyond the current representation additionally require a G3-instance</td></tr></tbody></table></div><p>H1 must not treat “any favorable result establishes the claim” as a rule across the three outcomes of resources, action, and coordination. H4 must not select favorable results after the fact among evidence coverage, safety of expression, behavior, and reflexive response. H5 must not search across multiple carriers or durability criteria for a surviving result. H5&#39;s <code>selected_carrier</code> must be one nonempty atomic reference, not a list, and <code>selected_carrier_family_id</code> must exactly match the selected subtype&#39;s <code>carrier_family_id</code>; otherwise, the instance is already ineligible before results are read. Multiple targets, multiple models, and multiple comparisons still require the single primary target or aggregation, model selection or ensembling, and correction rules to be frozen in <code>decision_rule</code>. When the positive-support check does not pass, the default is <code>unsupported_or_undecided</code>. Only when all of equivalence or sufficiency, statistical power or sensitivity, and tolerance in the pre-registered <code>null_decision_rule</code> pass is the state <code>null_supported</code>. An exploratory H-instance, one with post-evidence deviations, or one with undisclosed deviations generates only candidates or unresolved judgments; it must not upgrade the HV03, HV08, or H5 historical-carrier routes to empirically established claims.</p><p>H2, H3, and H6 do not enter this empirical instance contract. H2 is a rule for distinguishing uptake and responsibility types. H3 is a classification rule for institutional write-back. H6 is the normative boundary of open-ended undertaking. They may constrain how an interface is classified or where it stops, but cannot produce empirical mechanism support merely through successful classification. Even if an H-instance receives <code>supported</code>, it increases only the strength of description or explanation; it does not generate value, responsibility, obligation, normative justification, authorization, or real-world action.</p><h2 id="section-4-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.3</span><span class="xk-num__gap"></span></span>G1 Conditional Gain from Candidate Grouping <a class="header-anchor" href="#section-4-3" aria-label="Permalink to &quot;4.3 G1 Conditional Gain from Candidate Grouping {#section-4-3}&quot;">​</a></h2><p>Proposition: In an instance whose object, scale, time window, K, candidate grouping, and threshold have all been registered in advance, if the candidate grouping still achieves the predetermined out-of-sample gain relative to a complexity-matched N0 after controlling for the common environment, sampling or classification bias, and grouping leakage, and passes boundary-perturbation checks and review using independent time blocks or locations, then the grouping receives limited grouping-gain support under that SP/T/K.</p><p>G1 does not test “whether this object ultimately exists in the world.” It tests whether the current candidate grouping explains predetermined out-of-sample differences better than a complexity-matched N0 that does not use information from the grouping. G1a permits only <code>out_of_sample_predictive_gain</code>; G1b permits only <code>out_of_sample_intervention_gain</code>. Neither subtypes nor criteria may be exchanged after results appear. The common environment, sampling procedure, classification bias, grouping leakage, and model complexity must enter the controls or competing explanations.</p><p>The minimum positive support requires predetermined evaluation metrics and thresholds, an out-of-sample gain relative to N0, robustness to boundary perturbation, and review using independent time blocks or locations, with the instance also meeting support eligibility. If the out-of-sample gain does not pass the positive threshold, or the result is not reproduced under boundary perturbation or independent review, the default is only that G1 is not supported or that the result is unresolved. N0 may be supported, or the corresponding G1-instance refuted, only when the equivalence or sufficiency test and the checks for statistical power, sensitivity, and tolerance in the pre-registered <code>null_decision_rule</code> pass. If the object, grouping, success criterion, N0, decision rules, thresholds, data split, or leakage controls were not frozen before results, the instance is suspended. Passing G1 permits only the registration, within the specified SP/T/K, of the strength of grouping-gain support, the robustness of that gain to the boundary perturbations tested, and the grouping&#39;s applicable window. G1 support is only an eligibility relative to the declared explanatory or foresight task, not an overall threshold for object existence or object facts (see §10.1). It does not permit an ultimate ontological verdict, nor does it generate a subject, target, value, responsibility, or authorization.</p><h2 id="section-4-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.4</span><span class="xk-num__gap"></span></span>G2 Specified-Channel Effects and Per-Dimension Boundedness <a class="header-anchor" href="#section-4-4" aria-label="Permalink to &quot;4.4 G2 Specified-Channel Effects and Per-Dimension Boundedness {#section-4-4}&quot;">​</a></h2><p>Proposition: G2 must preselect exactly one subtype and success criterion before results appear. In a pre-specified carrier or channel instance, the channel is registered as a candidate for causally carrying that transition only when the preselected controlled perturbation, controlled intervention, or natural variation meeting identification conditions produces a difference in the specified state transition that exceeds a predetermined threshold. Capacity, delay, reliability, controllability, and loss must be measured separately, channel by channel and dimension by dimension; unmeasured dimensions are not established merely because the proposition holds.</p><p>G2a pre-registers controlled identification and must preselect exactly one of <code>controlled_perturbation_effect</code> and <code>controlled_intervention_effect</code>; “either perturbation or intervention succeeds” must not be written as a disjunctive criterion after the fact. G2b pre-registers natural variation meeting identification conditions, with <code>identified_natural_variation_channel_effect</code> as the only admissible criterion. Both subtypes must first specify the channel, target transition, quantity type and unit, comparative threshold, and dimensions to be measured. The null model is written only for the selected criterion: the preselected perturbation, intervention, or natural variation does not produce a difference in the target transition exceeding the threshold; criteria not preselected do not enter the instance&#39;s success or failure. Each bounded dimension separately takes no difference or a predetermined baseline as N0.</p><p>G2 does not claim that all causal processes have currently visible channels, nor that all channels are bounded in every dimension. Measuring delay alone does not permit capacity, reliability, controllability, and loss to be declared established along with it. Shifting may be traced further only for quantities of the same type, or quantities with explicit type conversion, units, an accounting boundary, and accounting rules. If the preselected criterion does not produce a difference above the threshold, the default record is only that positive G2 is not supported or is unresolved. The instance may be refuted only if it was pre-registered for falsification or a null judgment and the corresponding null-conclusion rule passes. When common inputs, alternative channels, or measurement protocols can explain the difference, support for the candidate channel should be withdrawn; favorable results on criteria that were not preselected cannot rescue it. G2 can locate only candidate causal carrying and the limits of measured dimensions. It cannot create a unified cost across domains, still less turn a carrier into a responsible party.</p><p>G2 tests specified channels and measured dimensions; it is not the sole entry point into all causal knowledge. If a qualified comparison identifies the total effect of a treatment while channels cannot yet be distinguished, the total effect should be retained and the channels marked unresolved; mechanisms must not be fabricated to fill in G2. If the total effect is near zero, that fact alone cannot negate local processes that offset or compensate for one another; the relevant processes still require independent evidence. When intervention implementation, common inputs, selection, or measurement conditions change, review the current claim again. Switching afterward to a favorable criterion does not recover the original confirmatory eligibility.</p><h2 id="section-4-5" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.5</span><span class="xk-num__gap"></span></span>Historical Formation, Current Carriers, and G3 Conditional Increments <a class="header-anchor" href="#section-4-5" aria-label="Permalink to &quot;4.5 Historical Formation, Current Carriers, and G3 Conditional Increments {#section-4-5}&quot;">​</a></h2><p>Historical research first distinguishes three questions: how earlier experiences form the current state; how current carriers retain, update, and continue to affect later outcomes; and whether historical materials still provide additional information or effects given the currently registered representation. The first two can hold while the third does not. Lack of support for the third also cannot establish that the first two hold. G3 tests only the third question; it cannot replace all research into historical causation, learning, accumulation, continuation, or reproduction.</p><p>Proposition: G3 must preselect exactly one subtype and success criterion before results appear. If historical variables have been defined before future outcomes are observed and provide reviewable out-of-sample conditional-increment information for a predetermined outcome after controlling for the currently registered state, environment, and measurement protocol, G3a can support predictive path dependence. Beyond that conditional increment, G3b must also preselect one criterion among history erasure, history recovery, or an equivalent intervention, and supports causal path dependence only when that criterion exceeds the predetermined threshold.</p><p>G3a tests predictive path dependence, with <code>historical_conditional_predictive_gain</code> as the only admissible criterion. G3b tests causal path dependence and must preselect exactly one of <code>history_erasure_effect</code>, <code>history_restoration_effect</code>, and <code>equivalent_intervention_effect</code>; it must not wait for results and then select a favorable result from erasure, recovery, or an equivalent intervention. The former requires historical variables to provide an out-of-sample conditional increment for a predetermined future outcome beyond the currently registered state; the latter additionally requires an outcome change under the preselected causal criterion. Both G3a and G3b take as their null that the currently registered state is a sufficient statistic and historical terms provide no conditional increment. G3b additionally requires no outcome change under its own preselected intervention criterion; criteria not preselected play no part in success or failure.</p><p>The preservation of traces is not the same as their entering future transitions; a predictive gain is not the same as history having causal efficacy, either. If historical variables are defined only after future results have been seen, current-state information is plainly omitted, or a subtype and success criterion have not been uniquely preselected, the instance is suspended. If historical terms provide no positive increment after controlling for the current state, environment, and measurement protocol, or if G3b&#39;s preselected criterion does not pass the positive threshold, the default record is only not supported or unresolved. A corresponding refutation is formed only when the frozen falsification or null-conclusion rule has been followed to completion. Other unselected criteria cannot be used to rescue the claim. Passing G3 permits only the registration of predictive or causal path differences within the pre-registered window; it does not permit inferences of historical fate, absolute irreversibility, responsibility, or authorization.</p><p>Scope of application: G3a and G3b are this framework&#39;s narrow classifications for “historical conditional increments beyond the currently registered state,” not definitions of all historical causation. Suppose earlier experience H changes current skill S, and S then affects outcome Y. If S already carries the relevant historical information sufficiently, H may add no further predictive information about Y given S. The narrow G3 condition is then not satisfied, but the historical formation process H→S→Y and learning in its general sense may still be supported by independent process materials or a research design. The total historical effect, current carrier, and conditional residual should be reported separately; G3 gains must not be manufactured by omitting known S. 〔Studies 03.03, 04.01–04.04, 24.04, 25.08〕</p><p>Intertemporal judgments register the carrier-transmission route and the historical-increment route separately. The carrier-transmission route requires a measured current state or carrier, grounds for how earlier inputs or changes entered that carrier, its retention or updating within the declared window, and longitudinal materials showing its continued effects on predetermined outcomes. Seeing only a lasting outcome or the existence of a carrier cannot confirm the carrier-transmission mechanism. A causal claim must additionally compare interruption, replacement, recovery, or natural variation meeting identification conditions under §2.4, and address common inputs, sustained exposure, selection, attrition, and measurement changes. When there are only correlational materials without the corresponding basis for identification, stop at an intertemporal description or a candidate mechanism.</p><p>Applying for formal mechanism support for the carrier branches below additionally requires an eligible G2-instance or the H-instance specified by that interface to support the relevant channel and outcome. H5 supports only traces within the selected carrier and window; it cannot by itself satisfy the check for subsequent effects or causation. The original instance&#39;s object, outcome, and window must cover the claim being made. A single immediate effect must not be extrapolated to a long-term effect, nor may several separately established local links be treated as a connected chain as a whole. Existing domain evidence still retains its own conclusions and limits under §2.1.1; the separation into routes in this section does not automatically confer eligibility as a G or H instance on it.</p><p>The historical-increment route separately tests conditional increments beyond the currently registered state under the G3 contract, with predictive and causal conclusions still kept separate. Carrier transmission can hold while G3 is not supported; failure of G3&#39;s positive-support check does not establish that carrier transmission holds, either. Known current states must not be omitted to obtain a historical increment, and routes must not be switched after results to rescue the original claim. Each route separately states its basis, competing explanations, failure conditions, and ceiling on conclusions. Accumulation, continuation, learning, delayed recovery, and intertemporal reproduction do not acquire support by being named.</p><p>Historical conditional increments depend on the choice of current representation; they must not be treated as an essence of the system independent of representation. Let the complete current state be <code>x_t</code>, the registered representation be <code>z_t=π(x_t)</code>, and the retained history be <code>h_t</code>. If history still provides an increment for a future target given <code>z_t</code>, this may be because <code>h_t</code> recovers current differences collapsed by <code>π</code>; that alone does not establish that the complete dynamics contains an additional history term. Proportionate comparisons should be made among available, task-relevant current carriers, measurement errors, and model complexity. Known current-state information must not be deliberately deleted to manufacture historical gains.</p><p>In reality, the complete state is usually unavailable. Thus, “can in principle be expanded into a sufficient state” must not be treated as having already established the absence of historical increments in this case. If the materials support only an increment relative to the currently registered state, report it under that representation, target, and window; redo the comparison when the representation changes. The value of using history to assist prediction, how history forms current carriers, and whether a narrow G3 instance receives support are three questions that can have different answers. Appendix C.11 gives an exact example of historical gains arising from omissions in the current state projection.</p></div>',1)),i(n,{section:"4.5"}),e[1]||(e[1]=t('<div class="theory-source"><h2 id="section-4-6" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.6</span><span class="xk-num__gap"></span></span>G4 Representational Closure and Object or Intervention Conversion <a class="header-anchor" href="#section-4-6" aria-label="Permalink to &quot;4.6 G4 Representational Closure and Object or Intervention Conversion {#section-4-6}&quot;">​</a></h2><p>Proposition: G4 must preselect exactly one subtype and one success criterion for that subtype before results appear. G4a, closure failure, may test conditional-increment information, conditional predictive gain, or conditional intervention gain from excluded scale variables given the retained variables at the target scale. G4b, object or intervention conversion, may test noncommutation between scale transformation M and object dynamics or intervention, failure of a target mapping to satisfy the pre-frozen K, changes in effective relations, or changes in intervention responses. Only when the preselected criterion exceeds the predetermined threshold or tolerance is the corresponding instance supported.</p><p>G4a and G4b answer different questions. G4a permits the success criteria <code>conditional_information_gain</code>, <code>conditional_predictive_gain</code>, and <code>conditional_intervention_gain</code>; each instance may preselect only one. Its null model is that, under the preselected criterion, the excluded scale variables provide no conditional increment beyond the threshold given the retained variables. G4b permits the success criteria <code>object_dynamics_non_commutation</code>, <code>intervention_non_commutation</code>, <code>identity_criterion_violation</code>, <code>effective_relation_change</code>, and <code>intervention_response_change</code>; each instance likewise may preselect only one. The null model is also written only for the selected item: object dynamics commute, interventions commute, the target mapping satisfies the pre-frozen K, effective relations do not change beyond tolerance, or intervention responses do not differ beyond tolerance. The five must not be combined into a disjunctive fallback.</p><p>General correlation, unconditional coupling, similar narratives, and omitted variables at the same scale are all insufficient to support G4. The instance is suspended if exactly one subtype and success criterion were not preselected before results, or if the D3/E5 mapping, comparison models, positive threshold, <code>null_decision_rule</code>, statistical-power or sensitivity check, and tolerance have not all been frozen. When the positive criterion passes, G4a registers only closure failure within the pre-registered variables, metrics, scales, and window; G4b registers only the preselected conversion candidate under the pre-registered mapping, K, scales, and window. When the positive criterion does not pass, the default record is only that G4 is not supported or is unresolved. Only when the equivalence or sufficiency test, statistical-power or sensitivity check, and tolerance in the null-conclusion rule actually pass may G4a register closure within the limits of the criterion, and G4b register that the preselected conversion was not detected. Merely being “not statistically significant” or not passing the positive threshold does not permit direct registration of closure, absence of object conversion, or equivalence of interventions. Unselected criteria must not be used for rescue or refutation. Passing G4 does not mean that higher scales are truer, more important, or have greater authority to act.</p><p>G4 maintains a symmetrical research interest in closure and nonclosure. Supporting closure within a specified scope under a registered test can show that a concise representation is already sufficient for the current task; detecting nonclosure shows that the representation, task, or scope of operations needs revision. <code>supported</code> and <code>null_supported</code> are only evidential states relative to the preselected factual assertion, not rankings of the quality of a method or of theoretical progress.</p><p>G4 comparisons must specify the targets, horizons, environments, and admissible operations relative to which closure is assessed. Sufficiency for prediction under ordinary conditions does not guarantee continued sufficiency under a new intervention; the same macro-level state may respond differently to the same operation because of differences in the composition collapsed by the representation. After an insufficiency is found, necessary variables may be added, composition or history retained, the set of actions limited, the horizon shortened, or the use narrowed. There is no need to recover all micro-level details. Closure holding can itself be a successful result of an effective macro-level description; emergence, aggregation, omissions at the same scale, and cross-boundary transmission do not universally require G4 closure failure.</p><p>Example of intervention sufficiency: two micro-level states A₁ and A₂ both have probability 0.2 of entering B under natural evolution, so merging them into A may be sufficient for this predictive task. Under a particular intervention, their probabilities of entering B are 0.8 and 0.1, respectively. The macro-level intervention outcome then depends on the share p of A₁, with probability 0.1+0.7p. One can then try adding only p rather than recovering all micro-level details. This teaching construction distinguishes predictive closure from intervention closure; it does not establish that real-world systems necessarily take these values. 〔Study 05.06〕</p></div>',1)),i(n,{section:"4.6"}),e[2]||(e[2]=t('<div class="theory-source"><h3 id="section-4-6-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.6.1</span><span class="xk-num__gap"></span></span>Formal Closure, Approximate Closure, and Empirical Eligibility <a class="header-anchor" href="#section-4-6-1" aria-label="Permalink to &quot;4.6.1 Formal Closure, Approximate Closure, and Empirical Eligibility {#section-4-6-1}&quot;">​</a></h3><p>In a deterministic model, if the source state space is X, the representation is π:X→Y with Y=π(X), and the one-step dynamics is F:X→X, then a macro-level update F̄:Y→Y satisfying π∘F=F̄∘π exists if and only if any two source states with the same representation still have the same representation after updating. This condition is an exact closure criterion within the model. If it holds throughout the state domain, commutation over multiple steps under fixed dynamics follows by induction; holding only at a few visited states cannot be extrapolated to closure over the entire domain. Sufficiency for a static query cannot replace this dynamic condition, either.</p><p>When multiple operations are admissible, the specific version of each operation should be declared and its update under state projection tested. If a macro-level operation does not determine its corresponding micro-level implementation, it is also necessary to check whether different admissible implementations yield identical macro-level responses or responses within tolerance. A stochastic model must test the conditional transition probabilities to each target state or target block; identical means alone are insufficient to establish closure of the distribution. Adding a particular composition proportion can repair a one-step prediction at a specified time, but does not automatically supply an update law for that proportion itself or closure under every operation.</p><p>Approximate closure must be tied to an error quantity, initial conditions, targets, an operation set, and a horizon. Suppose the per-step error under state projection is at most ε, and the Lipschitz constant of the proposed macro-level update on the relevant region does not exceed L. Starting from the same initial representation, the error at step t is then at most <code>ε∑_{j=0}^{t−1}L^j</code>; this bound requires the premises to hold at every step. When L&lt;1, a uniform upper bound ε/(1−L) is available; when L=1, the bound is tε; when L&gt;1, the error bound may increase rapidly. A one-step mean error or a short-term fitting error must not be substituted directly into this state-by-state, step-by-step bound.</p><p>These proofs provide structure under stated conditions; they do not confer real-world G4-instance support. Measurement, mapping, samples, operations, and error conditions must still be checked empirically, with the positive-support check and the null-conclusion check carried out separately. A formal proof of exact closure and failure to detect a deviation in limited data have different evidential statuses. Without sufficient sensitivity, the latter remains unresolved.</p><h2 id="section-4-7" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.7</span><span class="xk-num__gap"></span></span>A Fictional Group of Root Instances <a class="header-anchor" href="#section-4-7" aria-label="Permalink to &quot;4.7 A Fictional Group of Root Instances {#section-4-7}&quot;">​</a></h2><p>The following m1–m4 serve only to show how the contracts work. They describe a fictional transport model with multiple layers, cite no external observations, and constitute no empirical support for any G proposition.</p><p>m1 / G1a. The candidate object consists of several interconnected groups of units. B, X, T, SP, K, the grouping method, and a complexity-matched N0 are frozen in advance, and only <code>out_of_sample_predictive_gain</code> is selected, together with its metric and threshold. If the candidate grouping is effective only in the training sample, or if the gain disappears after a slight boundary perturbation, m1 fails. Limited grouping-gain support within that window is obtained only if the result is also reproduced in independent time blocks.</p><p>m2 / G2a. For m1&#39;s candidate object, specify a transmission channel and target state transition in advance, select only <code>controlled_perturbation_effect</code>, then block the channel under controlled conditions. If the blockage changes the target transition by more than the threshold, the channel may be registered only as a candidate for causal carrying. Suppose only delay is measured in this example; capacity, reliability, controllability, and loss remain unknown and cannot be established along with m2.</p><p>m3 / G3a. First define the historical variable “backlog in the preceding three rounds,” select only <code>historical_conditional_predictive_gain</code>, then control for the current queue, environmental inputs, and measurement protocol. If the historical term still provides an out-of-sample conditional increment for the next round&#39;s outcome, predictive path dependence may be registered. Without an intervention for history erasure or recovery, this must not be upgraded to causal path dependence.</p><p>m4 / G4a. Before results, select only the closure-failure subtype and <code>conditional_information_gain</code>, and freeze the micro-level and aggregated scales, M, retained variables, excluded variables, metric, and threshold. Closure failure within that window is registered only if the excluded local temporal sequence provides a conditional increment above the threshold under that criterion given the aggregate variables. A predictive or intervention gain must not be substituted after results are seen, nor may the record be rewritten as G4b object conversion.</p><p>This example shows that the four instances can generate further questions for one another, but do not replace one another. Passing m1 does not guarantee that m2&#39;s channel is effective; passing m2 does not guarantee m3&#39;s historical effect; and passing m3 does not guarantee m4&#39;s scale-closure failure.</p><h2 id="section-4-8" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.8</span><span class="xk-num__gap"></span></span>Epistemic Constraints E1–E5 <a class="header-anchor" href="#section-4-8" aria-label="Permalink to &quot;4.8 Epistemic Constraints E1–E5 {#section-4-8}&quot;">​</a></h2><h3 id="section-4-8-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.8.1</span><span class="xk-num__gap"></span></span>E1 Constraint on Object Declaration <a class="header-anchor" href="#section-4-8-1" aria-label="Permalink to &quot;4.8.1 E1 Constraint on Object Declaration {#section-4-8-1}&quot;">​</a></h3><p>For the current judgment, E1 requires the object, scope, scale, time window, necessary variables, and the object&#39;s identity conditions to be explicit; comparative claims must separately specify the corresponding baseline or null model. When a field is missing, state which inferred conclusion it limits and how, without canceling independently established source facts because of a missing format field. Incomplete D0 fields do not permit the analyst&#39;s grouping to be declared an objective structure; ordinary facts, textual meanings, and mathematical proofs are still reviewed under their own evidence and burden of argument.</p><h3 id="section-4-8-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.8.2</span><span class="xk-num__gap"></span></span>E2 Observation Position and Model Limits <a class="header-anchor" href="#section-4-8-2" aria-label="Permalink to &quot;4.8.2 E2 Observation Position and Model Limits {#section-4-8-2}&quot;">​</a></h3><p>Observation positions, measurement channels, and model choices limit what is visible; one record must not be treated as the object&#39;s entire state. Nor is it presupposed that every specific task must add perspectives. Whether a representation is sufficient depends on the target, horizon, environment, and admissible operations. Invisibility is not the same as nonexistence. When blind spots relevant to the task are substantial, evidence should be added, the use narrowed, or the judgment kept unresolved; whether probing is possible still requires comparing risks, windows, and authorization.</p><h3 id="section-4-8-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.8.3</span><span class="xk-num__gap"></span></span>E3 Conditional Observational Participation <a class="header-anchor" href="#section-4-8-3" aria-label="Permalink to &quot;4.8.3 E3 Conditional Observational Participation {#section-4-8-3}&quot;">​</a></h3><p>Observational participation is registered only when observation, naming, scoring, or publication enters into actual causal coupling with the object. Temporal order alone, or a mechanism story that “being observed changes the object,” is insufficient to pass. A channel must be located, and a counterfactual established for no observation, alternative observation, or blockage.</p><h3 id="section-4-8-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.8.4</span><span class="xk-num__gap"></span></span>E4 Retaining Competing Explanations and Residuals <a class="header-anchor" href="#section-4-8-4" aria-label="Permalink to &quot;4.8.4 E4 Retaining Competing Explanations and Residuals {#section-4-8-4}&quot;">​</a></h3><p>In an explanation, competing accounts that the materials permit and that are sufficient to change the judgment should be compared, and counterexamples and unexplained residuals retained. The competition must specify what is disputed: the size of an effect, its mechanism, contextual meaning, the scope of extrapolation, or normative premises. Compatible explanations can bear responsibilities at different layers. When no reasonable competing explanation is available, one must not be fabricated merely to fill a quota; the scope of the search and failure conditions must still be stated. Openness, love, complexity, or a sense of theoretical wholeness cannot fill gaps in evidence. How competing explanations that have not yet been distinguished limit action must be judged in conjunction with harm, reversibility, external obligations, and current permissions.</p><h3 id="section-4-8-5" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.8.5</span><span class="xk-num__gap"></span></span>E5 Testing Cross-Scale Transfer <a class="header-anchor" href="#section-4-8-5" aria-label="Permalink to &quot;4.8.5 E5 Testing Cross-Scale Transfer {#section-4-8-5}&quot;">​</a></h3><p>Cross-scale transfer must pass D3&#39;s tests of the mapping, invariants, changed items, lost items, error, competing explanations, and residuals. The only hard inferential premise for E5 is D3; E1, E4, EVIDENCE, and ANALOGY are all method checks. They do not enter the inferential acyclic graph, nor masquerade as additional empirical causes. E5 does not depend on G4 being true; conversely, every G4-instance must pass E5. Expansion of observational scope does not imply expansion of authorization scope, and the J axis must not be extrapolated automatically along with the other scale axes.</p><h2 id="section-4-9" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.9</span><span class="xk-num__gap"></span></span>Evidential Status of Human-Experience Clauses <a class="header-anchor" href="#section-4-9" aria-label="Permalink to &quot;4.9 Evidential Status of Human-Experience Clauses {#section-4-9}&quot;">​</a></h2><p>H1 (meaning and coordination), H4 (power, mediation, and reflexivity), and H5 (historical carriers) are families of empirical hypotheses awaiting testing. The specific factual assertions for all three are tested against their objects and evidence. This procedure grants eligibility for formal support only to an H-instance for which <code>human_empirical_instance_contract</code> has been completed and the corresponding criteria met; definitions, interfaces, and the framework&#39;s own formulations are not external empirical support. Without eligible external instance records, <code>empirical_evidence_records=[]</code>, and the evidential status is <code>requires_instance_evidence</code>.</p><p>Thus, H1 must preselect exactly one outcome family among resources, action, or coordination in each case and test differences in meaning arrangements. H4 must preselect exactly one outcome family among evidence coverage, safety of expression, object behavior, or reflexive response in each case, then establish the channel and counterfactual for position, mediation, or disclosure conditions. H5, “historical trace carriers,” must preselect exactly one carrier family, one specific atomic carrier reference, and one durability criterion. Only if the family matches the subtype and the historical event, baseline, trace observables, threshold, and durability window were all frozen before results may a passing selected criterion permit registration of candidate traces within the specified carrier and window, and submission of predefined candidate historical variables to a G3-instance. Historical path increments beyond the current state and C4&#39;s corresponding repair window are assessed separately under G3/C4. Historical effects transmitted by current carriers and general effects of intervention timing obtain independent grounds under §4.5 and §6.10, respectively; protection, harm reduction, or repair actions separately undergo C12, explicit N premises, and O procedures. Proposition names, internal definitions, or this framework&#39;s own narrative cannot complete instance testing on behalf of these three hypothesis families.</p><h2 id="section-4-10" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.10</span><span class="xk-num__gap"></span></span>Outcome Contracts and Mechanism Conditions C1–C12 <a class="header-anchor" href="#section-4-10" aria-label="Permalink to &quot;4.10 Outcome Contracts and Mechanism Conditions C1–C12 {#section-4-10}&quot;">​</a></h2><p>Each contract delimits the outputs that may be registered according to its own definitions, empirical basis, additional conditions, or normative and procedural premises; branches that depend on root instances must obtain the corresponding instance support. Inferential dependencies list the hard premises that enter the acyclic inference graph; method checks list protocol requirements, which determine whether a judgment may be released but do not serve as empirical causes. Domain specialization and applicability relations are explained separately in the body. The following four fixed contract fields remain synchronized with the outcome contracts, while evidence, counterexamples, and failure boundaries are presented together by groups of inferred conclusions.</p><p>The C identifiers serve different argumentative tasks. C1, C2, the historical-increment branch of C4, and C6 primarily register the outcomes within specified limits already supported by the corresponding empirical instances, adding a scope of use. C3, C5, C7, and C9–C11 must also combine separately listed mechanism, temporal, or domain conditions. The basic C8 pattern depends on separately obtained evidence of variation, differential retention, and reproduction; C12 is a check for normative procedures. A shared numbering scheme does not turn these into empirical laws of the same kind. Nor does citing the same materials again in a root instance and an inferred conclusion constitute a second piece of independent support.</p><h2 id="section-4-11" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.11</span><span class="xk-num__gap"></span></span>Group 1: Objects, Carrying, and Feedback <a class="header-anchor" href="#section-4-11" aria-label="Permalink to &quot;4.11 Group 1: Objects, Carrying, and Feedback {#section-4-11}&quot;">​</a></h2><h3 id="section-4-11-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.11.1</span><span class="xk-num__gap"></span></span>C1 Grouping Gain and Its Robustness to Boundary Perturbation <a class="header-anchor" href="#section-4-11-1" aria-label="Permalink to &quot;4.11.1 C1 Grouping Gain and Its Robustness to Boundary Perturbation {#section-4-11-1}&quot;">​</a></h3><p>Inferential dependencies: D0; G1</p><p>Additional conditions: Use a G1-instance that has completed pre-registration and obtained support for the current instance. Several items have already been frozen. They include the candidate object S* and N0. The evaluation threshold is fixed as well. So are the extrapolation unit and the boundary-perturbation plan.</p><p>Permitted conclusions: Within that SP/T/K and extrapolation unit, the following results may be registered. They are the strength of support for the grouping gain, the robustness of that gain to the boundary perturbations tested, and the window in which the candidate grouping applies.</p><p>Prohibited leaps: Do not turn limited support for the grouping gain into an ultimate ontological verdict. Do not treat whether G1 support has been obtained as the overall threshold for an object’s existence. Do not infer a natural boundary, unified subject, common target, or S0–S6 stage. This support does not establish the value of persistence. It also does not establish how responsibility should be allocated. It cannot determine a choice. It cannot establish authorization to act.</p><p>Method checks: E1; E4; EVIDENCE</p><p>The derivation first uses D0 to freeze the candidate object without presupposing that the grouping yields a gain, then reads the out-of-sample gain of the same G1-instance relative to a complexity-matched N0. Finally, boundary perturbation and independent review are combined to register the strength of support and applicable window.</p><h3 id="section-4-11-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.11.2</span><span class="xk-num__gap"></span></span>C2 Carrying and Channel Constraints <a class="header-anchor" href="#section-4-11-2" aria-label="Permalink to &quot;4.11.2 C2 Carrying and Channel Constraints {#section-4-11-2}&quot;">​</a></h3><p>Inferential dependencies: D0; G2</p><p>Additional conditions: Use a pre-registered G2-instance that has obtained support for the current instance. When discussing shifting, the source and target quantities must be of the same type or have an explicit type conversion. The quantities&#39; units and equality criteria have been frozen. The time window is fixed as well. So is the accounting boundary. The conversion mapping or accounting rules are also fixed. Capacity, delay, reliability, controllability, and loss are registered channel by channel and dimension by dimension. Unmeasured dimensions remain unknown.</p><p>Permitted conclusions: Candidate causal carrying for a specified state transition may be registered, together with channel limits within the measured types, units, windows, and dimensions. Shifting may be traced only when the conditions for quantities of the same type and for mapping are satisfied.</p><p>Prohibited leaps: Do not treat quantities of different types or nonconvertible quantities as a unified cost. Do not generalize from one measured, bounded dimension to all dimensions or all channels. Being a carrier or a channel cannot by itself establish who bears responsibility or costs. Do not infer the responsible party from that role alone. The same applies to the cost bearer. Do not derive conservation across domains from the occupation of resources.</p><p>Method checks: E1; E4; CAUSAL; EVIDENCE</p><p>The derivation holds only for the specified channel, target transition, and measured dimensions. Quantities of the same type can be traced through equality of units; quantities of different types must go through explicit conversion or an accounting mapping. Unmeasured dimensions and quantities outside the boundary remain unknown, rather than being recorded as conserved, vanished, or costs already shifted.</p><h3 id="section-4-11-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.11.3</span><span class="xk-num__gap"></span></span>C3 Effective Feedback and Feedback-Mediated Learning <a class="header-anchor" href="#section-4-11-3" aria-label="Permalink to &quot;4.11.3 C3 Effective Feedback and Feedback-Mediated Learning {#section-4-11-3}&quot;">​</a></h3><p>Inferential dependencies: D2; G2</p><p>Additional conditions: The feedback branch must have a return channel, temporal order, changed fields, and a counterfactual with no return or a blocked channel. The required effect is a change in at least one subsequent state, probability, or constraint. It need not leave a durable historical trace. The carrier-learning branch separately checks the update carrier, retention or updating rules, subsequent invocation over multiple rounds, a predetermined task comparison, and the corresponding causal evidence under §4.5. The historical-increment learning branch additionally requires a G3-instance, updates that can be retained, repeated rounds, and a predetermined task comparison.</p><p>Permitted conclusions: The basic branch may register effective feedback, its time lag, and the fields it acts on. When the carrier-learning branch&#39;s conditions hold, candidate feedback-mediated learning may be registered within the specified updates, task, and window. With an additional G3-instance, updates that can be retained, and repeated rounds, candidate historical-increment feedback-mediated learning may be registered.</p><p>Prohibited leaps: Equating a feedback entry point or proof of receipt with effective feedback; equating one state update with learning, repair, or positive improvement; inferring a direction of value or authorization to act directly from facts about feedback or learning.</p><p>Method checks: E4; CAUSAL; EVIDENCE</p><p>The basic branch uses a G2-instance to identify candidate causal carrying in the return channel, then compares conditions with a return against no return or blockage under D2. Carrier learning must trace how updates are retained, invoked in subsequent rounds, and affect the predetermined task, checking longitudinal and causal materials under §4.5; sufficiency of the current state does not negate this route. Historical-increment learning additionally requires G3 to provide an increment beyond the currently registered state. The two kinds of evidence cannot substitute for one another.</p><p>The branches are registered as <code>C3-feedback</code> (a return channel, changes in subsequent states or transitions, and a blocking counterfactual), <code>C3-carried-learning</code> (additional evidence under §4.5 of an update carrier, invocation over multiple rounds, and task outcomes), and <code>C3-learning</code> (the historical-increment kind; additionally G3, with updates that can be retained, repeated rounds, and an out-of-sample comparison on a predetermined task).</p><div class="xk-table"><table><thead><tr><th>Contract<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></th><th>Minimum Evidence</th><th>Key Counterexamples</th><th>Failure Boundary</th></tr></thead><tbody><tr><td>C1</td><td>Complete D0; a G1-instance passing the pre-registration check; out-of-sample gain, boundary perturbation, and independent review</td><td>The gain disappears in an independent block; slight boundary perturbation invalidates it; N0 absorbs the entire gain</td><td>Return to candidate grouping when G1 does not pass or SP/T/K is exceeded</td></tr><tr><td>C2</td><td>G2 passing the threshold; quantity types, units, equality or conversion mappings; measurement channel by channel and dimension by dimension; accounting boundary and window</td><td>A redundant channel replaces it completely; quantities of different types lack a mapping; common inputs explain the difference</td><td>When the channel, quantities of the same type, equality of units, or conversion mapping are insufficient, describe only inputs, occupation, loss, or candidate limits</td></tr><tr><td>C3</td><td>Return channel, temporal sequence, blocking counterfactual, and changed fields; carrier learning additionally has update retention, invocation over multiple rounds, and a task comparison; historical-increment learning additionally has G3</td><td>Signals arrive but transitions do not change; updates are not retained or invoked; common inputs or proxy indicators explain the difference</td><td>With no return or subsequent change, describe only signal arrival; when evidence for the learning route is insufficient, stop at effective feedback; absence of G3 blocks only the historical-increment branch</td></tr></tbody></table></div><h2 id="section-4-12" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.12</span><span class="xk-num__gap"></span></span>Group 2: History, Load, Scale, and Spillovers <a class="header-anchor" href="#section-4-12" aria-label="Permalink to &quot;4.12 Group 2: History, Load, Scale, and Spillovers {#section-4-12}&quot;">​</a></h2><h3 id="section-4-12-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.12.1</span><span class="xk-num__gap"></span></span>C4 Historical Effects, Path Differences, and Repair Windows <a class="header-anchor" href="#section-4-12-1" aria-label="Permalink to &quot;4.12.1 C4 Historical Effects, Path Differences, and Repair Windows {#section-4-12-1}&quot;">​</a></h3><p>Inferential dependencies: D1; the historical-increment branch additionally requires G3, while the current-carrier and intervention-timing branches obtain the corresponding evidence under §4.5 and §2.4.</p><p>Additional conditions: Historical variables for the G3 branch must be defined before future results, with the currently registered state, environment, and measurement protocol controlled; the predictive and causal subtypes of historical increments must not be conflated. Obtain evidence for general historical formation and for the effects of current carriers through the separate route set out in §4.5. Discussion of a repair window additionally requires K*/F* made public in advance, comparisons of intervention at different times, and the corresponding causal identification. G3 is added only when an additional historical residual is claimed.</p><p>Permitted conclusions: The G3 branch may register predictive or causal historical increments within the pre-registered window and under the current representation. The current-carrier route may register limited historical effects according to its own materials. With additional K*/F*, timing comparisons, and the corresponding basis for identification, a conditional repair window may be registered; this does not require the outcome to retain a historical residual beyond the current state.</p><p>Prohibited leaps: Equating trace preservation with a historical effect; equating predictive gain with causation or irreversibility; equating path differences with fate, progress, decline, responsibility, or regression to an earlier stage; claiming repair before K*/F* have been disclosed.</p><p>Method checks: E1; E4; CAUSAL; EVIDENCE</p><p>Evolution is first classified under D1; historical effects cannot be inferred from a definition. The current-carrier route checks formation, retention, invocation, and subsequent outcomes; the historical-conditional-increment route reads G3a&#39;s predictive gain or G3b&#39;s causal basis separately. A repair window compares how interventions at different times affect the attainability of K*/F* made public in advance and the price to be paid. The corresponding G3 responsibility is borne only when a historical residual beyond the current representation is also claimed.</p><h3 id="section-4-12-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.12.2</span><span class="xk-num__gap"></span></span>C5 Load, Capacity, and Recovery <a class="header-anchor" href="#section-4-12-2" aria-label="Permalink to &quot;4.12.2 C5 Load, Capacity, and Recovery {#section-4-12-2}&quot;">​</a></h3><p>Inferential dependencies: D0; G2</p><p>Additional conditions: The instantaneous branch must have definitions of demand and capacity of the same type, units or a conversion mapping, measurement within the same window, and distribution across positions. The carrier-accumulation branch must trace how load enters the current damage or capacity state, the process of accumulation or recovery across windows, and its subsequent effects under §4.5, and satisfy G2&#39;s channel requirements; the historical-increment accumulation branch additionally requires a G3-instance and a locatable historical carrier.</p><p>Permitted conclusions: The basic branch may register an instantaneous load–capacity shortfall at a specified window and position. When carrier-accumulation conditions hold, candidate cumulative damage or delayed recovery may be registered within that carrier, window, and outcome. With an additional G3-instance, candidate historical-increment accumulation or delayed recovery beyond the current state may be registered.</p><p>Prohibited leaps: Claiming that load necessarily accumulates monotonically or that overload necessarily causes collapse; directly subtracting demand and capacity of different types; treating an instantaneous shortfall as automatic proof of durable damage; allowing a need for recovery to directly generate an obligation of sacrifice for a named subject.</p><p>Method checks: E1; E4; CAUSAL; EVIDENCE</p><p>The basic branch freezes the types and units of demand, capacity, replenishment, loss, and the time window, uses a G2-instance to confirm the carrying channel, then compares the immediate shortfall and spillover positions within the same window. Accumulation and delayed recovery require materials spanning windows: the carrier route identifies how historical load forms the current state, how that state is maintained or recovers, and how it affects subsequent outcomes under §4.5; the historical-increment route separately uses G3 to test increments beyond the currently registered state. Sufficiency of the current state is compatible with a carrier explanation, but cannot replace evidence of its formation process and causation.</p><p>The branches are registered as <code>C5-instant</code> (a demand–capacity mapping for quantities of the same type and measurement within the same window), <code>C5-carried-cumulative</code> (additional evidence under §4.5 of a current carrier, accumulation or recovery across windows, and subsequent effects), and <code>C5-cumulative</code> (the historical-increment kind; additionally G3, with a historical carrier and subsequent differences in capacity or recovery).</p><h3 id="section-4-12-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.12.3</span><span class="xk-num__gap"></span></span>C6 Scale Closure and Object Conversion <a class="header-anchor" href="#section-4-12-3" aria-label="Permalink to &quot;4.12.3 C6 Scale Closure and Object Conversion {#section-4-12-3}&quot;">​</a></h3><p>Inferential dependencies: D3; G4</p><p>Additional conditions: Before results, preselect exactly one of G4a and G4b, and from that subtype&#39;s <code>allowed_success_criteria</code> freeze exactly one <code>selected_success_criterion</code>. M(SP0→SP1), retained items, changed items, lost items, error, comparison models, positive thresholds, and tolerance have been frozen. Registering single-scale closure within a specified scope or failure to detect the preselected conversion requires passing the checks in <code>null_decision_rule</code>. The equivalence or sufficiency test must be frozen before results and must actually pass. The rule may use a check of statistical power. It may use a sensitivity check instead. The check used and the tolerance must also be frozen before results and must actually be met.</p><p>Permitted conclusions: G4a&#39;s single-scale closure failure within pre-registered variables, metrics, scales, and windows, or G4b&#39;s object/intervention conversion within pre-registered mappings, K, scales, and windows, may be registered separately. When the positive criterion does not pass, the default record is only not supported or unresolved. Only when the pre-registered equivalence or sufficiency test and the checks for statistical power, sensitivity, and tolerance pass may closure within the limits of the criterion be registered for G4a, or failure to detect the preselected conversion for G4b; neither may be extrapolated to unselected criteria.</p><p>Prohibited leaps: Using general correlation, unconditional coupling, or omissions at the same scale to support G4; combining G4a and G4b after the fact; changing success criteria within the same subtype after the fact or using unselected criteria to rescue the claim; directly calling a result that is not statistically significant or does not pass the positive threshold single-scale closure, absence of object conversion, or equivalence of interventions; treating a wider scale range as a truer explanation or greater authorization; treating a shared term as proof of object or intervention identity.</p><p>Method checks: E4; E5; EVIDENCE</p><p>G4a separately tests conditional increments from excluded scale variables. G4b tests only its preselected item among noncommutation of object dynamics, noncommutation of intervention, failure of the pre-frozen K, change in effective relations, or change in intervention response. The G4-instance cited by C6 must have frozen both one subtype and one success criterion before results; switching is prohibited after results, whether between subtypes or within one subtype.</p><h3 id="section-4-12-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.12.4</span><span class="xk-num__gap"></span></span>C7 Local Improvement and Cross-Boundary Spillover <a class="header-anchor" href="#section-4-12-4" aria-label="Permalink to &quot;4.12.4 C7 Local Improvement and Cross-Boundary Spillover {#section-4-12-4}&quot;">​</a></h3><p>Inferential dependencies: G2; claims that actually cross scales additionally require a D3/E5 mapping, and claims of closure failure or object/intervention conversion further require the corresponding G4 instance.</p><p>Additional conditions: The local target, object boundary, window of impact, and variables outside the boundary have been registered. A G2-instance locates the cross-boundary channel, with temporal order, a mechanism bridge, and a blocking or substitution counterfactual between the local change and the outcome outside the boundary. Crossing an object boundary or an administrative boundary does not automatically constitute a change of scale; D3/E5 is checked separately when scales are actually crossed. The corresponding G4 is tested separately only when closure failure, object conversion, or intervention conversion is additionally claimed. Using “externality” requires stating the costs and benefits and who bears or receives them. These must be specified within the institutional or accounting arrangements at issue.</p><p>Permitted conclusions: Cross-boundary spillover accompanying local improvement, together with its distribution across positions, may be registered when the mechanism bridge and counterfactual hold; it is called an externality only when an additional institutional or accounting definition is available.</p><p>Prohibited leaps: Claiming that every local improvement necessarily harms a larger scale; directly calling cross-boundary correlation a spillover mechanism; calling something an externality without an institutional or accounting definition; automatically assigning compensation, responsibility, or an action plan upon finding a spillover.</p><p>Method checks: E4; CAUSAL; EVIDENCE; additionally E5 when scales are actually crossed.</p><p>First measure the predetermined improvement in the local target, then trace outputs, risks, resource occupation, or signals outside the boundary along the channel specified by G2, using proportionate comparisons to distinguish a common shock from a cross-boundary effect. When making a cross-scale statement, specify the D3/E5 mapping; when stating scale-closure failure or object conversion, provide the corresponding G4 evidence. A model with sound closure can also represent cross-boundary effects correctly; inadequacy of a model must not be made a necessary condition for the existence of an effect. The institutional or accounting definition further determines whether the costs and benefits at issue are externalities.</p><div class="xk-table"><table><thead><tr><th>Contract</th><th>Minimum Evidence</th><th>Key Counterexamples</th><th>Failure Boundary</th></tr></thead><tbody><tr><td>C4</td><td>The historical-increment branch requires G3 and control of the current representation; the carrier route obtains evidence under §4.5; the repair branch requires K*/F*, timing comparisons, and the corresponding causal basis</td><td>Carrier formation or subsequent effects have not been distinguished; the residual is absorbed by a sufficient current state; intervention timing makes no stable difference</td><td>Absence of G3 blocks only additional historical increments; without causal evidence, do not call it historical causation; without K*/F* and a timing basis, do not call it a repair window</td></tr><tr><td>C5</td><td>G2-instance; demand and capacity of the same type or a conversion mapping; measurement by position within the same window; carrier accumulation requires formation, retention, recovery, and causal comparison across windows; the historical-increment kind additionally has G3</td><td>Capacity expands at the same time; demand and capacity are incomparable; no subsequent difference remains after the shortfall is removed; sustained common inputs explain the outcome</td><td>When type, unit, window, or channel is insufficient, describe only a limited resource state; insufficient evidence across windows does not establish an accumulation mechanism; absence of G3 blocks only the historical-increment branch</td></tr><tr><td>C6</td><td>Complete D3/E5, preselected G4 subtype and criterion, competing explanations, and the corresponding review; a positive conclusion requires a record that the preselected criterion passed; a null conclusion requires records of passing the corresponding equivalence or sufficiency, statistical power or sensitivity, and tolerance requirements; the two routes are established separately, neither being a premise for the other</td><td>Retained variables form a sufficient statistic; the gain comes from omissions at the same scale or from complexity; M commutes with dynamics/intervention and the mapping is stable; insufficient sample or measurement sensitivity prevents the positive-support check from passing but cannot support the null either</td><td>Return to the source scale if the contract is incomplete, the subtype or criterion was not preselected, an unselected criterion is used for rescue, or the result is not reproduced; remain unresolved if neither the positive-support check nor the null-conclusion rule passes</td></tr><tr><td>C7</td><td>Local variables and variables outside the boundary; a channel specified by G2, temporal sequence, and counterfactual; D3/E5 additionally for a cross-scale claim; G4 additionally for a claim of closure failure or object conversion; an institutional/accounting definition additionally for an externality</td><td>Blocking the channel has no effect; a common shock explains the difference; the claimed cost does not fall within that accounting definition</td><td>Without cross-boundary causation, register only correlation or an accounting gap; closure holding does not negate spillover; without the corresponding definition of where costs and benefits fall, no externality classification is obtained</td></tr></tbody></table></div><p>Crossing boundaries, crossing scales, and model closure answer different questions. Transmission at the same scale can have real effects. So can cost shifting across administrative boundaries. Synchronized changes caused by a common cause do not become cross-boundary effects through correlation alone. Existing domain evidence is retained according to its research design. When using C7&#39;s formal mechanism route, check the channel, mapping, and accounting conditions actually required by the claimed level. 〔Studies 04.05, 20.07, 26.02, 28.02〕</p><h2 id="section-4-13" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.13</span><span class="xk-num__gap"></span></span>Group 3: Patterns of Evolution, Observation, Human Uptake, and Institutional Write-Back <a class="header-anchor" href="#section-4-13" aria-label="Permalink to &quot;4.13 Group 3: Patterns of Evolution, Observation, Human Uptake, and Institutional Write-Back {#section-4-13}&quot;">​</a></h2><h3 id="section-4-13-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.13.1</span><span class="xk-num__gap"></span></span>C8 Variation–Differential Retention–Reproduction <a class="header-anchor" href="#section-4-13-1" aria-label="Permalink to &quot;4.13.1 C8 Variation–Differential Retention–Reproduction {#section-4-13-1}&quot;">​</a></h3><p>Inferential dependencies: D1</p><p>Additional conditions: V: distinguishable variations and their sources are defined before results; D: differences in outcomes exceeding a threshold occur in comparable environments; R: those differences enter the next round and can be reviewed across repeated rounds; random drift, common external causes, sampling bias, and one-time shocks serve as competing explanations; a claim about a specific carrying mechanism additionally requires a G2-instance.</p><p>Permitted conclusions: When V, D, R, entry into the next round, repeated rounds, and comparison with random drift as a competing explanation all hold, a variation–differential retention–reproduction pattern may be registered within the specified environment; a specific carrying mechanism is registered only with an additional G2-instance.</p><p>Prohibited leaps: Explaining every instance of evolution through selection; equating a single instance of persistence or a single sample difference with differential retention; treating what is retained as better, more advanced, or more justified; equating systemic selection with a subject&#39;s choice, collective governance, or authorization.</p><p>Method checks: E4; CAUSAL; EVIDENCE</p><p>C8 is a contract for testing a pattern that requires independent evidence; it cannot be proved directly from a definition or the framework&#39;s narrative. The basic-pattern branch requires V, D, R, entry into the next round, repeated rounds, and comparison with random drift as a competing explanation to hold together. The specific-mechanism branch additionally requires a G2-instance to locate the retention or reproduction channel. It describes systemic selection, not an acting subject&#39;s intentional choice, still less authorization for governance.</p><p>The branches are registered as <code>C8-pattern</code> (V, D, R, the next round, repeated rounds, and comparison with random drift as a competing explanation) and <code>C8-mechanism</code> (additionally G2, with a specified retention or reproduction channel and channel perturbation or natural variation).</p><h3 id="section-4-13-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.13.2</span><span class="xk-num__gap"></span></span>C9 Observation Channels and Reflexive Responses <a class="header-anchor" href="#section-4-13-2" aria-label="Permalink to &quot;4.13.2 C9 Observation Channels and Reflexive Responses {#section-4-13-2}&quot;">​</a></h3><p>Inferential dependencies: G2</p><p>Additional conditions: Observation, naming, scoring, or publication reaches the object through an actual specified channel; the object&#39;s response has temporal order and a counterfactual involving no observation, a different observation, or a blocked channel. The carrier route for a lasting response must check how the response enters the current state, how it is retained or updated across windows, and its sustained effects under §4.5, distinguishing sustained observation, repeated stimulation, and common changes. Historical-increment lasting reflexivity additionally requires a G3-instance.</p><p>Permitted conclusions: Observational participation or a reflexive response may be registered within a specified channel and window. When the conditions for continuation through a carrier hold, a reflexive response maintained through the current carrier may be registered within that window. With an additional G3-instance, historical-increment lasting reflexivity beyond the current state may be registered.</p><p>Prohibited leaps: Claiming that all observation changes its object; equating a reaction after observation with the object&#39;s original essence; treating reflexivity as automatic authorization to conceal or suppress observation, or to act on the object.</p><p>Method checks: E2; E3; E4; CAUSAL; EVIDENCE</p><p>The derivation first freezes the observation position, measurement protocol, and existing blind spots, then uses a G2-instance to identify the observation event&#39;s specified propagation channel, establishing a counterfactual through no observation, alternative observation, or channel blockage. A single reaction supports only a reflexive response within the corresponding window. Continuation across windows requires separate checks of the carrier, updates, and evidence of subsequent effects under §4.5; repeated stimulation must not be treated as retention of a single impact. The historical-increment lasting branch is entered only when G3 shows a historical increment across windows beyond the current state.</p><p>The branches are registered as <code>C9-response</code> (an actual channel and counterfactual), <code>C9-carried-persistence</code> (additionally a current carrier, continuation or updating across windows, and causal comparison under §4.5), and <code>C9-persistent</code> (the historical-increment kind; additionally G3, with a historical conditional increment and review across windows).</p><h3 id="section-4-13-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.13.3</span><span class="xk-num__gap"></span></span>C10 Human Uptake and Intertemporal Reproduction <a class="header-anchor" href="#section-4-13-3" aria-label="Permalink to &quot;4.13.3 C10 Human Uptake and Intertemporal Reproduction {#section-4-13-3}&quot;">​</a></h3><p>Inferential dependencies: G2</p><p>Additional conditions: The object is a structure involving human action or care. A structure involving maintenance or institutional execution also qualifies. H2 separately registers uptake carriers, bearers of costs of the same type, beneficiaries, rights to stop, and responsible parties. The carrier-reproduction route must check the retention, replenishment, replacement, and actual continuation of capabilities, rules, resources, or relations over multiple cycles under §4.5, with G2 channel evidence covering the corresponding outcomes and windows; the historical-increment intertemporal branch additionally requires a G3-instance. A claim about historical traces in the H5 sense additionally requires an H5 instance; traces alone do not establish reproduction.</p><p>Permitted conclusions: The basic branch may register the human uptake chain and its current distribution. When the carrier route&#39;s conditions hold, candidate intertemporal uptake or reproduction may be registered within specified cycles and carriers. With an additional G3, candidate historical-increment intertemporal reproduction beyond the current state may be registered. With an additional H5 instance, historical traces may be delimited within its scope of support.</p><p>Prohibited leaps: Equating capability for uptake with an obligation of uptake; equating the most visible executor with the responsible party; treating H2 classification itself as proof of a reproduction mechanism; directly authorizing a particular subject&#39;s sacrifice, continuation, or exit from the existence of an uptake chain.</p><p>Method checks: H2; E4; CAUSAL; EVIDENCE</p><p>C10 specializes to structures involving human action, care, maintenance, or institutional execution. The current-uptake branch uses G2 to locate a specified channel and separates uptake carriers, bearers of costs of the same type, beneficiaries, rights to stop, and responsible parties under H2. The intertemporal carrier branch must separately check continuation across consecutive cycles and its causal evidence; the historical-increment intertemporal branch additionally requires G3. H5 supports only historical traces within its contract&#39;s scope and cannot replace evidence of effects for either intertemporal route. H2 is an operational check, not an empirical cause.</p><p>The branches are registered as <code>C10-current</code> (H2 typing and a channel specified by G2), <code>C10-carried-reproduction</code> (additionally intertemporal carriers, replenishment or replacement, actual continuation, and causal evidence under §4.5), <code>C10-intertemporal</code> (the historical-increment kind; additionally G3, with an intertemporal historical increment), and <code>C10-historical-carrier</code> (a carrier qualification on the historical-increment branch; additionally G3 and H5, with a human historical-carrier instance).</p><h3 id="section-4-13-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.13.4</span><span class="xk-num__gap"></span></span>C11 Institutional Write-Back <a class="header-anchor" href="#section-4-13-4" aria-label="Permalink to &quot;4.13.4 C11 Institutional Write-Back {#section-4-13-4}&quot;">​</a></h3><p>Inferential dependencies: D2; G2</p><p>Additional conditions: The object has institutional fields such as records, rules, resources, roles, responsibilities, memory, or stopping conditions. H3 serves as a classification check. It requires feedback to cause field changes. It also requires actual execution. Intake, field changes, execution, and duration are recorded separately.</p><p>Permitted conclusions: Intake, field changes, actual execution, effective write-back, and its duration within an institution may be distinguished.</p><p>Prohibited leaps: Equating the existence of an appeal or audit entry point with effective write-back; equating a single write-back with long-term repair or positive improvement; treating the fact of institutional write-back as proof that the institution is justified or its authorization has expanded.</p><p>Method checks: H3; E4; CAUSAL; EVIDENCE</p><p>C11 uses G2 to locate an institutional return channel, compares conditions with a return against no return or blockage under D2, then distinguishes intake, field changes, and actual execution under H3. Duration is part of the write-back contract; a single write-back is not the same as learning. <code>C3-carried-learning</code> separately checks update retention, invocation over multiple rounds, and task outcomes; the historical-increment branch <code>C3-learning/CM-LEARNING-history</code> additionally requires G3, updates that can be retained, and repeated rounds (see §4.5 and §6.3).</p><div class="xk-table"><table><thead><tr><th>Contract</th><th>Minimum Evidence</th><th>Key Counterexamples</th><th>Failure Boundary</th></tr></thead><tbody><tr><td>C8</td><td>Sources of V; D in comparable environments; an R channel, the next round, and repeated rounds; random drift/common external causes as competing explanations; G2 additionally for the mechanism branch</td><td>Common inputs produce the pattern simultaneously; differences do not enter the next round; random drift suffices; perturbing the reproduction channel has no effect</td><td>If any of V/D/R/next round/repeated rounds is missing, register only change or a single difference; without G2, do not call it a specific mechanism</td></tr><tr><td>C9</td><td>Observation position, propagation channel, G2-instance, temporal sequence, and a no-observation/alternative-observation/blocking counterfactual; continuation through a carrier additionally has retention, updating, and comparison across windows; the historical-increment lasting branch additionally has G3</td><td>No change after the channel is blocked; changes precede observation; sustained stimulation or common inputs explain subsequent changes</td><td>Without a channel or counterfactual, do not register observational participation; without evidence across windows, do not extrapolate continuation; absence of G3 blocks only the historical-increment lasting branch</td></tr><tr><td>C10</td><td>G2-instance; H2 typing and a cost mapping for quantities of the same type; comparisons of replenishment/rotation/load reduction/exit/replacement; intertemporal carriers additionally have evidence of continuation across consecutive cycles; the historical-increment intertemporal branch additionally has G3, and the trace qualification additionally has H5</td><td>In the carrier branch, continuation does not occur or is explained by common inputs; in the historical-increment branch, the current state absorbs all historical differences</td><td>If H2 fields cannot be separated, register only a data gap; insufficient intertemporal evidence does not establish a reproduction mechanism; absence of G3 blocks only the historical-increment intertemporal branch; absence of H5 prevents its formal trace eligibility</td></tr><tr><td>C11</td><td>G2-instance; institutional return channel and a blocking counterfactual; changes in fields before and after, with actual execution; duration</td><td>Only a receipt or a statement of position; field changes are not executed; independent orders explain the changes</td><td>Without field changes, describe only intake; without execution, describe only record updating; intertemporal mechanisms must not be extrapolated from a single write-back</td></tr></tbody></table></div><h2 id="section-4-14" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.14</span><span class="xk-num__gap"></span></span>Group 4: Normative Bridging Checks <a class="header-anchor" href="#section-4-14" aria-label="Permalink to &quot;4.14 Group 4: Normative Bridging Checks {#section-4-14}&quot;">​</a></h2><h3 id="section-4-14-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.14.1</span><span class="xk-num__gap"></span></span>C12 Check on the Validity of Normative Bridging <a class="header-anchor" href="#section-4-14-1" aria-label="Permalink to &quot;4.14.1 C12 Check on the Validity of Normative Bridging {#section-4-14-1}&quot;">​</a></h3><p>Inferential dependencies: N1; O1; O2; O3; O4</p><p>Additional conditions: O1 has frozen an auditable description, evidential status, and the action ceiling supported by the description. O2 registers <code>explicit_normative_premise_ids</code>, positive targets or constraint properties, conflicts, and dissent at runtime. O3 registers the authorizing subject, source, jurisdiction, validity period, J axis, candidate options, and the non-action option. O4 registers constrained execution, monitoring, stopping, appeal, review, rollback, remedy, expiry, and renewed authorization. The protection floor has been checked item by item. N1 alone can only block overreach; it cannot generate a positive option.</p><p>Permitted conclusions: Only when the auditable description, explicit N premises at runtime, protection floor, authorization on the J axis, and all of O1–O4 pass may a constrained recommendation eligible for real-world adoption be formed. Forming an analytical recommendation for deliberation requires explicit normative premises, evidence, and the price to be paid, but does not require authorization already to have been obtained for real-world execution that has not yet occurred. If only N1 is present or positive N is missing, the only permitted outputs are non-action, obtaining further evidence, or continued deliberation.</p><p>Prohibited leaps: Inferring an “ought” directly from facts about stability, efficiency, persistence, coherence, paths, or selection; treating expert explanation, model confidence, wide impact, or legal validity, each on its own, as normative justification; inferring love, responsibility, a requirement of sacrifice, or authority to act from G1–G4, C1–C11, or S0–S6; filling in an option&#39;s target with normative principles that have not been explicitly cited.</p><p>Method checks: EVIDENCE; PF-1; PF-2; PF-3; PF-4; PF-5; PF-6; PF-7; PF-8; PF-9; PF-10</p><p>C12 is not an empirical inferred conclusion, but a check on procedural validity before description enters real-world choice. It requires all 10 bridging components to appear: <code>descriptive_or_explanatory_claim_ids</code>, <code>current_evidence_and_epistemic_constraints</code>, <code>explicit_normative_premise_ids</code>, <code>normative_conflict_record</code>, <code>protection_floor_status</code>, <code>authorization_and_jurisdiction_record</code>, <code>options_including_no_action</code>, <code>operational_procedure_records</code>, <code>action_ceiling</code>, and <code>stop_review_rollback_and_remedy</code>. N1 is a negative check against overreach; it cannot produce a positive option on its own.</p><div class="xk-table"><table><thead><tr><th>Minimum Evidence</th><th>Key Counterexamples</th><th>Failure Boundary</th></tr></thead><tbody><tr><td>O1 description freezing and evidence audit; O2 explicit N premises and conflicts; O3 authorization and comparison of options; O4 constrained execution and correction; protection floor and J axis</td><td>The same facts lead to different choices under different N; only N1 is present without a positive target; authorization does not cover the action; stopping, correction, or rollback is inaccessible</td><td>Real-world action must not begin if any required explicit N premise is missing. The same applies if the protection floor, J-axis authorization, or the O1–O4 record is missing. If only N1 is present, retain the negative check against overreach.</td></tr></tbody></table></div><h2 id="section-4-15" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.15</span><span class="xk-num__gap"></span></span>Combined Conditions and Evidence Routes <a class="header-anchor" href="#section-4-15" aria-label="Permalink to &quot;4.15 Combined Conditions and Evidence Routes {#section-4-15}&quot;">​</a></h2><p>The relation between root instances and additional conditions can be condensed into the following condition trees:</p><p>G1-instance + object/variable bridge + G2-instance └─ Candidate channel on which the specified form of organization depends ├─ + Return channel and blocking counterfactual │ └─ Effective feedback │ ├─ + Current update carrier + invocation over multiple rounds and task comparison (§4.5) │ │ └─ Candidate carrier-transmission feedback-mediated learning │ └─ + G3-instance + updates that can be retained + repeated rounds │ └─ Candidate historical-increment feedback-mediated learning └─ + G4a/G4b + D3/E5 mapping └─ Candidate closure failure or object/intervention conversion</p><p>G2-instance + mapping of demand/capacity of the same type └─ Candidate instantaneous overload ├─ + Current carrier + accumulation/recovery across windows and causal comparison (§4.5) │ └─ Candidate carrier-transmission cumulative damage or delayed recovery └─ + G3-instance + historical carrier └─ Candidate historical-increment cumulative damage or delayed recovery beyond the current state</p><p>D1 + V + D + R + next round + repeated rounds + comparison with random drift as a competing explanation └─ Variation–differential retention–reproduction pattern ├─ + G2-instance → specified retention/reproduction mechanism └─ + G3-instance → candidate historical path across rounds</p><p>Listing the names of G instances alone does not constitute sufficient conditions for a mechanism; the corresponding additional conditions, method checks, bridging evidence, and limits of application must also hold. When conditions are complete, register limited results under the specific contract. When conditions are incomplete, identify the gap and the conclusion it blocks without withdrawing independently supported content. Even if every instance in a particular set of G1–G4 instances passes, this does not imply an S0–S6 stage, direction, value, responsibility, choice, or authorization; these conclusions each require their own classification, normative, and procedural contracts.</p><h2 id="section-4-16" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.16</span><span class="xk-num__gap"></span></span>Scope and Stopping Points of Empirical Judgments <a class="header-anchor" href="#section-4-16" aria-label="Permalink to &quot;4.16 Scope and Stopping Points of Empirical Judgments {#section-4-16}&quot;">​</a></h2><p>Empirical judgments provide descriptions and limited explanations constrained by the object, scale, time window, evidence, and extrapolation unit. Specific factual assertions within G question families must be tested through instances; C registers existing results or combines mechanism conditions; F provides proofs under formal premises; and real-world mechanisms still require independent instance evidence. Definitions, identifiers, examples, and internal descriptions cannot determine whether an empirical proposition holds in the world. Further evaluation of value, responsibility, sacrifice, choice, or how the situation should be handled requires adding human-domain typing, normative reasons, and O1–O4 procedures. Empirical conclusions must not bypass these responsibilities on their own.</p><h2 id="section-4-17" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.17</span><span class="xk-num__gap"></span></span>Common Method Constraints <a class="header-anchor" href="#section-4-17" aria-label="Permalink to &quot;4.17 Common Method Constraints {#section-4-17}&quot;">​</a></h2><p>Method constraints govern how analysts construct, check, and use models; they do not claim how the world necessarily works. They may be questioned and revised, and their use must be evaluated through comparisons of actual reductions in error, gains in understanding, and costs of use.</p><h3 id="section-4-17-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.17.1</span><span class="xk-num__gap"></span></span>CMC1 Tasks and Representations Must Be Declared Together <a class="header-anchor" href="#section-4-17-1" aria-label="Permalink to &quot;4.17.1 CMC1 Tasks and Representations Must Be Declared Together {#section-4-17-1}&quot;">​</a></h3><p>Objects, layering, coarse and fine scales, and target variables are tied to the task, observation position, horizon, environment, and use. A conversion must check what is retained, collapsed, omitted, and added. It must not be presumed lossless, nor may it be claimed conversely that every conversion necessarily causes a task-relevant loss. Whether the target representation suffices to recover an answer, advance dynamics, or evaluate admissible interventions is tested separately; whether different orders of conversion are equivalent is also tested separately. The distinctions on which the task depends must be retained. Recovering every detail unconditionally is unnecessary.</p><h3 id="section-4-17-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.17.2</span><span class="xk-num__gap"></span></span>CMC2 The Status of Materials and Scope of Support Must Be Traceable <a class="header-anchor" href="#section-4-17-2" aria-label="Permalink to &quot;4.17.2 CMC2 The Status of Materials and Scope of Support Must Be Traceable {#section-4-17-2}&quot;">​</a></h3><p>Reports, observations, model beliefs, and formal proofs retain their respective statuses. So do simulation outputs and execution receipts. Each inference specifies the new information, premises, and rules it uses. Processing the same data again must not be counted as a new independent observation. A simulated state can become the starting point of the next simulation, but recursive depth alone cannot add empirical support or raise a capability level. New computations or proofs can improve understanding of existing materials, but their gains come from inspectable arguments and must not be packaged as new real-world samples.</p><h3 id="section-4-17-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.17.3</span><span class="xk-num__gap"></span></span>CMC3 Facts, Values, and Eligibility to Act Are Established Separately <a class="header-anchor" href="#section-4-17-3" aria-label="Permalink to &quot;4.17.3 CMC3 Facts, Values, and Eligibility to Act Are Established Separately {#section-4-17-3}&quot;">​</a></h3><p>Facts, predictions, formal feasibility, and technical capability cannot by themselves generate value, responsibility, or authority to act. Analytical recommendations disclose normative targets, evidence, the price to be paid, and dissent. Real-world adoption additionally requires valid permissions, a protection floor, implementation resources, and conditions for stopping and remedy. Normative premises constrain choice; they do not in turn prove empirical mechanisms true.</p><h3 id="section-4-17-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.17.4</span><span class="xk-num__gap"></span></span>Method Effectiveness and Evaluation of the Framework <a class="header-anchor" href="#section-4-17-4" aria-label="Permalink to &quot;4.17.4 Method Effectiveness and Evaluation of the Framework {#section-4-17-4}&quot;">​</a></h3><p>G question families organize empirical testing; their number does not establish sufficient coverage. C contracts organize the use of results; their completeness does not establish real-world reliability. Testing whether the entire framework is worth using should involve a separate comparison with an adequate specialist method or a simpler approach, using common targets, materials, and budgets. The comparison should ask whether the framework reduces substantive errors, whether it preserves necessary distinctions, and whether it improves explanation or decision-making. It should also assess whether the costs are proportionate. Without such a comparison, only the intended uses and checked local results may be stated.</p><p>The effect of an individual instance, a question family&#39;s rate of applicability within a particular set of objects, and the framework&#39;s net gain on a specified task are three different empirical targets. Sampling units, scopes of extrapolation, and evaluation rules must each be registered; a batch of successful instances or a large volume of reading materials must not be treated as proof of universal effectiveness.</p><h2 id="section-4-18" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.18</span><span class="xk-num__gap"></span></span>Conditional Formal Propositions <a class="header-anchor" href="#section-4-18" aria-label="Permalink to &quot;4.18 Conditional Formal Propositions {#section-4-18}&quot;">​</a></h2><p>The following propositions hold within explicit mathematical objects. They provide checkable conditions for representation, conversion, and action, not unmeasured laws of reality. Real-world application must additionally check variable mappings, assumptions, errors, and scope of application under §2.1.2. Proving that a function exists does not guarantee that it is computable, available in time, implementable, or authorized for adoption.</p><h3 id="section-4-18-1" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.18.1</span><span class="xk-num__gap"></span></span>F1 Task Recovery <a class="header-anchor" href="#section-4-18-1" aria-label="Permalink to &quot;4.18.1 F1 Task Recovery {#section-4-18-1}&quot;">​</a></h3><p>Let X be a nonempty state domain, with representation π:X→Y and Y=π(X), and target q:X→V. A decoder g:Y→V using only the representation and satisfying q=g∘π exists if and only if π(x)=π(x′) always implies q(x)=q(x′). When this holds, g is unique on Y. In other words, the same representation cannot merge states for which the current task requires different answers. See Appendix C.6 for the proof and for bounds on scalar recovery error on a finite state domain.</p><h3 id="section-4-18-2" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.18.2</span><span class="xk-num__gap"></span></span>F2 Closure under Dynamics and Admissible Interventions <a class="header-anchor" href="#section-4-18-2" aria-label="Permalink to &quot;4.18.2 F2 Closure under Dynamics and Admissible Interventions {#section-4-18-2}&quot;">​</a></h3><p>Let F:X→X be deterministic one-step dynamics. A macro-level update F̄ satisfying π∘F=F̄∘π exists if and only if any two source states with the same representation still have the same representation after updating. If this holds throughout the state domain, evolution over any finite number of steps under fixed dynamics commutes. With an admissible action set U, this condition must hold separately for every <code>F_u</code>. Check whether each action can be implemented across the relevant source states sharing a representation. Check the different micro-level implementations as well. Sufficiency for static recovery does not automatically satisfy closure under dynamics or intervention; a stochastic model must also compare the complete transition probabilities to target blocks. See Appendix C.8 for the proof.</p><h3 id="section-4-18-3" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.18.3</span><span class="xk-num__gap"></span></span>F3 Common Feasible Actions under Information Constraints <a class="header-anchor" href="#section-4-18-3" aria-label="Permalink to &quot;4.18.3 F3 Common Feasible Actions under Information Constraints {#section-4-18-3}&quot;">​</a></h3><p>For a finite, single-round deterministic task, let the current materials be compatible with a nonempty set of states <code>X_y</code>, and let each state x have a set of eligible actions <code>A_ok(x)</code> already determined according to the target, protections, resources, and valid permissions. An action based only on the current representation y that qualifies in every compatible state exists if and only if <code>∩_{x∈X_y}A_ok(x)</code> is nonempty. Identifying every state is therefore not a universal prerequisite for bounded action, while the availability of a solution in each state separately does not guarantee that the right choice can be made now. See Appendix C.12 for the proof; randomized and sequential strategies must establish their own conditions.</p><h3 id="section-4-18-4" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.18.4</span><span class="xk-num__gap"></span></span>F4 Task Preservation through Successive Conversions <a class="header-anchor" href="#section-4-18-4" aria-label="Permalink to &quot;4.18.4 F4 Task Preservation through Successive Conversions {#section-4-18-4}&quot;">​</a></h3><p>Let f:X→Z and h:Z→W, with the first stage satisfying q=g∘f. The composition h∘f can still recover the same final target q if and only if g is constant on every fiber of h restricted to the actual image f(X). Completion of different local tasks at the individual steps cannot replace this shared-endpoint condition. Preservation under a functional representation, causal effects connected in sequence, and joint implementation using shared resources are checked separately; a single flag marking a connection cannot substitute for these different checks. See Appendix C.7 and C.12 for the proof and counterexamples.</p><h3 id="section-4-18-5" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.18.5</span><span class="xk-num__gap"></span></span>F5 Error Propagation under Approximate Closure <a class="header-anchor" href="#section-4-18-5" aria-label="Permalink to &quot;4.18.5 F5 Error Propagation under Approximate Closure {#section-4-18-5}&quot;">​</a></h3><p>Let the target space have a metric d. Assume that the one-step projection error is no greater than ε at every state reached, and that the Lipschitz constant of the proposed macro-level update on the relevant region is no greater than L. Starting from the same initial representation, the error after t steps satisfies <code>e_t≤ε∑_{j=0}^{t−1}L^j</code>. This bound requires the error and region conditions to continue to hold at every step; mean fitting error cannot directly replace a state-by-state bound. When L&lt;1, there is an upper bound ε/(1−L); when L=1, it is tε; when L&gt;1, the upper bound may increase rapidly. See Appendix C.8 for the proof.</p><h2 id="section-4-19" tabindex="-1"><span class="xk-num"><span class="xk-num__n">4.19</span><span class="xk-num__gap"></span></span>Task Families and Dynamic Refinement <a class="header-anchor" href="#section-4-19" aria-label="Permalink to &quot;4.19 Task Families and Dynamic Refinement {#section-4-19}&quot;">​</a></h2><p>Which distinctions a structural representation should retain depends on the tasks at issue and the operations allowed to act on the object. A finer representation can preserve more differences and also increases measurement, storage, explanation, and maintenance costs; not every detail is a necessary input to every task. In a fully specified finite deterministic model, it is possible to state precisely which states can be merged and compute the coarsest partition satisfying particular requirements.</p><p>Let X be a nonempty finite state set, Q a finite set of target functions <code>q:X→V_q</code>, and U a finite set of admissible actions. Each u∈U corresponds to a total deterministic update <code>F_u:X→X</code>; the actions are implementable in every state, and no unregistered external disturbance is introduced here. The empty action string denotes no update. For an action string <code>w=u₁…u_k</code>, write <code>F_w=F_{u_k}∘…∘F_{u₁}</code>. These conditions delimit the objects of the proposition below; they cannot be assumed satisfied merely because real-world operations share a name.</p><p><strong>F6 The Coarsest Sufficient Partition for a Task Family.</strong> For a nonnegative integer H, define <code>x∼_H x′</code> if and only if, for every q∈Q and every admissible action string w of length no greater than H, <code>q(F_w(x))=q(F_w(x′))</code>. This is an equivalence relation. The representation formed by its equivalence classes retains precisely the task answers within the given horizon. Any deterministic representation that answers these questions exactly may merge only states within the same equivalence class.</p><p>Proof: Reflexivity, symmetry, and transitivity follow from the corresponding properties of equality of function values. The answer for every target and action string is constant within an equivalence class, so by F1 it is uniquely determined by that class. If another representation merges two nonequivalent states, then by definition there must be a target and an admissible action string giving different answers; by F1, that representation cannot recover both answers exactly. Thus, the partition induced by any sufficient representation is finer than or equal to this partition. This coarseness concerns a state partition relative to X, Q, U, and H; it does not establish the fewest parameters, the cheapest measurement, or the irreplaceability of a particular natural-language concept.</p><p>Sufficiency for a fixed finite horizon does not automatically produce dynamic closure for that same horizon. Take X={a,b,c,d}, with the sole target q(a)=q(b)=q(c)=0 and q(d)=1, and the sole action satisfying F(a)=c, F(b)=b, F(c)=d, and F(d)=d. States a and b both give 0 now and after one step, so a∼₁b. Their successors c and b, however, give different answers after one further step, so c and b do not belong to the same ∼₁ class. For H≥1, what is always guaranteed is that <code>x∼_H x′</code> implies <code>F_u(x)∼_{H−1}F_u(x′)</code>. The remaining horizon should be reduced when advancing, or closure of the fixed partition under admissible actions must be required separately.</p><p>To preserve every target under admissible action strings of any finite length, define <code>x∼_*x′</code> to hold when the answers agree for all such finite strings. This partition is closed under each <code>F_u</code>. Prepending u to any subsequent string gives a string already compared in the definition. Conversely, any representation that recovers all targets in Q and is closed under all <code>F_u</code> can be advanced step by step and used to recover the targets after any finite string, so the partition it induces must be finer than or equal to <code>∼_*</code>. Thus <code>∼_*</code> is the unique coarsest state partition satisfying these conditions. Uniqueness is determined by the equivalence classes, irrespective of their labels.</p><p>On a finite domain, this partition can be computed directly. Begin by grouping states by their values on all current targets to form P₀. Each round uses only the preceding partition <code>P_h</code> and splits its blocks synchronously by the signature <code>([x]_{P_h},([F_u(x)]_{P_h})_{u∈U})</code> to obtain <code>P_{h+1}</code>. Here <code>[x]_{P_h}</code> denotes the block containing x in the preceding partition. Each strict refinement adds at least one block, so at most <code>|X|−1</code> strict refinements can occur. Once no block splits further, the blocks preserve the current targets and satisfy closure under each action. Level H of synchronous iteration corresponds exactly to target comparisons for strings of length at most H, so the stable partition equals <code>∼_*</code>. With asynchronous refinement one block at a time, final stability can still be checked. Its operation count must not be used as the horizon H here. This procedure is computable on a complete finite table. It does not guarantee identification of true states from incomplete observations, much less tractability for large models within a given budget.</p><p>This result gives a conditional rule for simplification. Merge states that cannot be distinguished by the given targets and admissible operations. Retain a distinction only when a task or an operation actually distinguishes the states. Adding targets or admissible actions leaves the required partition unchanged or refines it. Shortening the horizon, narrowing the use, or restricting the operations can make a simpler representation sufficient. Adjusting the task can yield a legitimate new question, but the adjustment does not warrant declaring the original task complete.</p><p>Error tolerances require separate analysis. The condition “the two answers differ by no more than ε” is generally not transitive. The values 0 and ε are close, and ε and 2ε are close, but 0 and 2ε may differ by more than the tolerance. Approximate similarity therefore cannot directly replace the equivalence relation above or automatically yield a unique coarsest partition. One may use a bound on block diameter, worst-case recovery error, or a specified probabilistic loss. The optimal solution, stability, and computational cost for each require separate proof.</p><p>This section states a proposition about sets and dynamics in a finite model. Distinguishing states by input strings, forming equivalence classes, and refining them recursively have a direct mathematical connection to Moore’s work on sequential machines. The preservation of states and actions also connects to abstraction in controlled dynamics. The explicit finite model and proof in this section establish the conclusion without relying on additional optimality results for other classes of machines. 〔Moore, 1956, pp. 143 and 145–146; Ravindran and Barto, 2003〕 It neither declares that nature has a single correct hierarchy nor reduces people’s legitimate claims to the current predictive targets. Which targets must be preserved, which actions may be implemented, and what error is acceptable still have to be determined separately on the basis of domain facts, normative reasons, and real-world permissions. When these givens are challenged, they are handled under §2.14.</p></div><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Translator&#39;s note: A contract here is an analytical agreement registered and frozen before results, close to pre-registration; it is not a legal instrument. <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>Translator&#39;s note: A contract here is an analytical agreement registered and frozen before results, close to pre-registration. It is not a legal instrument. <a href="#fnref2" class="footnote-backref">↩︎</a></p></li></ol></section>',3))])}const g=a(c,[["render",d]]);export{b as __pageData,g as default};
